//! The markup documents of the theme that are embedded as assets: the ones
//! that are left out of the theme and not compiled.
//!
//! The table is generated by the build script of the crate from the files
//! of the crate directory (the counterpart of the resource items of the
//! upstream project file).

use crate::ASSEMBLY;
use ferroui_base::platform::register_assets;

include!(concat!(env!("OUT_DIR"), "/assets.rs"));

/// A control theme document that is embedded but not part of the theme
/// yet, because it names types that are not ported.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ExcludedDocument {
    /// The rooted asset path of the document (`/Controls/Calendar.xaml`).
    pub path: &'static str,
    /// The types the document needs that do not exist yet.
    pub missing_types: &'static str,
}

/// The control theme documents `Controls/SimpleControls.xaml` does not
/// merge yet, from `Controls/excluded.txt`.
pub fn excluded_documents() -> &'static [ExcludedDocument] {
    EXCLUDED
}

/// Whether the document with the rooted asset path `path` is left out of
/// the theme. (Used by the tests of the crate: the constructor of the theme
/// loads the documents its class document includes.)
#[cfg(test)]
pub(crate) fn is_excluded(path: &str) -> bool {
    EXCLUDED.iter().any(|excluded| excluded.path == path)
}

/// Every document of the crate, as `(rooted asset path, content)`.
#[cfg(test)]
pub(crate) fn documents() -> &'static [(&'static str, &'static [u8])] {
    DOCUMENTS
}

/// The content of the embedded document with the rooted asset path `path`.
#[cfg(test)]
pub(crate) fn document(path: &str) -> Option<&'static [u8]> {
    DOCUMENTS.iter().find(|(asset_path, _)| *asset_path == path).map(|(_, content)| *content)
}

/// Registers the embedded documents with the asset loader under the name
/// of the assembly of the theme (which makes the assembly known to it, so
/// that a load by URI reaches the loader table of the compiled markup).
///
/// The tests register every document of the crate: they load the compiled
/// documents with the run-time loader as well, to compare the two, and the
/// generator of `compiled_xaml.rs` reads them as the compiler reads its
/// sources.
pub(crate) fn register() {
    #[cfg(not(test))]
    register_assets(ASSEMBLY.name, ASSETS);
    #[cfg(test)]
    register_assets(ASSEMBLY.name, DOCUMENTS);
}
